"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["312"],{393447(n){n.exports=JSON.parse('{"id":8728,"title":"\u852C\u83DC\u8BE6\u60C5\u98753","description":"\u4F60\u73B0\u5728\u662F\u4E00\u4F4D\u751F\u9C9C\u7535\u5546\u7684\u9876\u7EA7\u89C6\u89C9\u8BBE\u8BA1\u5E08\uFF0C\u9700\u5B8C\u6210\u4EE5\u4E0B\u4EFB\u52A1\uFF1A\u6839\u636E\u63D0\u4F9B\u7684\u852C\u83DC\u540D\u79F0\uFF0C\u5148\u521B\u4F5C\u4E00\u4EFD\u9002\u914D\u5BB6\u5EAD\u70F9\u996A\u573A\u666F\u7684**\u5317\u65B9\u83DC\u7CFB**\u8BE6\u7EC6\u83DC\u8C31\uFF0C\u518D\u63CF\u8FF0\u8BE5\u83DC\u8C31\u6210\u54C1\u7684\u751F\u9C9C\u7535\u5546\u5E73\u53F0\u5C55\u793A\u6548\u679C\u56FE\uFF08\u9700\u7B26\u5408\u5E73\u53F0\u201C\u65B0\u9C9C\u3001\u5065\u5EB7\u3001\u6613\u70F9\u996A\u201D\u7684\u6838\u5FC3\u8C03\u6027\uFF0C\u4E14\u573A\u666F\u7B80\u7EA6\u5E72\u51C0\uFF09\u3002\\n\u9996\u5148\uFF0C\u4F60\u5C06\u6536\u5230\u4EE5\u4E0B\u852C\u83DC\u540D\u79F0\uFF1A\\n<vegetable> </vegetable>\\n\u4EE5\u4E0B\u662F\u6838\u5FC3\u8981\u6C42\uFF1A\\n<\u6838\u5FC3\u8981\u6C42>\\n\u4E3B\u6807\\n\u82B1\u6837\u5403\u6CD5\uFF0C\u6FC0\u53D1\u4F60\u7684\u70F9\u996A\u7075\u611F\\n - \u5185\u5BB9\u7C7B\u578B\uFF1A\u5C0F\u7EA2\u4E66\u98CE\u683C\u7F8E\u98DF\u957F\u56FE\uFF0C\u6392\u7248\u4E25\u683C\u9075\u5FAA\u5DE6\u53F3\u5DE6\u9519\u843D\uFF0C\u5DE6\u7B2C1\u680F\uFF0C\u53F3\u7B2C2\u680F\uFF0C\u5DE6\u53F33\u680F\u5E76\u5217\u5C55\u793A\u4EA7\u54C1\u6599\u7406\u98DF\u8C31\uFF0C\u6BCF\u680F\u5FC5\u987B\u5305\u542B\u300C\u83DC\u54C1\u6807\u9898+\u98DF\u6750\u5217\u8868+\u6B65\u9AA4\u6587\u5B57+\u5BF9\u5E94\u6210\u54C1\u56FE\u300D4\u4E2A\u6A21\u5757\\n- \u89C6\u89C9\u98CE\u683C\uFF1A\u6574\u4F53\u80CC\u666F\u4E3A\u6D45\u767D\u8272\u5927\u7406\u77F3\u7EB9\u7406\uFF0C\u8FB9\u7F18\u70B9\u7F00\u65B0\u9C9C\u753B\u9762\u660E\u4EAE\u6E05\u65B0\uFF0C\u8272\u5F69\u9C9C\u4EAE\u81EA\u7136\u5149\u7EBF\u4E3A\u67D4\u548C\u81EA\u7136\u5149\uFF08\u6A21\u62DF\u7A97\u8FB9\u62CD\u6444\u6548\u679C\uFF0C\u5E26\u8F7B\u5FAE\u9634\u5F71\u589E\u5F3A\u7ACB\u4F53\u611F\uFF09\\n- \u6587\u5B57\u89C4\u8303\uFF1A\u7B80\u4F53\u4E2D\u6587\uFF0C\u5B57\u4F53\u4E3A\u5706\u6DA6\u6E05\u6670\u7684\u201C\u601D\u6E90\u9ED1\u4F53\u201D\uFF0C\u6807\u9898\u5B57\u53F718pt\uFF08\u52A0\u7C97\uFF09\u3001\u98DF\u6750/\u6B65\u9AA4\u6587\u5B57\u5B57\u53F712pt\uFF0C\u6587\u5B57\u989C\u8272\u4E3A\u6DF1\u68D5\u8272\uFF0C\u6392\u7248\u6574\u6D01\u5206\u5C42\uFF08\u6A21\u5757\u95F4\u75281px\u6D45\u7070\u8272\u865A\u7EBF\u5206\u9694\uFF09\\n</\u6838\u5FC3\u8981\u6C42>\\n\u4EE5\u4E0B\u662F\u5206\u680F\u7EC6\u8282\uFF08\u6BCF\u79CD\u98DF\u8C31\u9519\u843D\u6392\u7248\uFF09\uFF1A\\n<\u5206\u680F\u7EC6\u8282>\\n1. **\u53F3\u7B2C\u4E00\u680F\uFF08\u521B\u610F\u8F7B\u98DF\uFF09**\uFF1A\\n- \u83DC\u54C1\u6807\u9898\uFF1A\uFF08\u9700\u7F6E\u4E8E\u680F\u5185\u9876\u90E8\u5C45\u4E2D\uFF0C\u4E25\u683C\u6309\u4EA7\u54C1\u540D\u79F0\u751F\u6210\uFF09\\n- \u98DF\u6750\u5217\u8868\uFF1A\u6309\u4EA7\u54C1\u540D\u79F0\u751F\u6210\u5BF9\u5E94\uFF08\u6BCF\u884C1\u79CD\u98DF\u6750\uFF0C\u524D\u7F6E\u25CF\u7B26\u53F7\uFF09\\n- \u6B65\u9AA4\u6587\u5B57\uFF1A\u6309\u4EA7\u54C1\u540D\u79F0\u751F\u6210\u5BF9\u5E94\u98DF\u8C31\uFF08\u6309\u5E8F\u53F7\u6392\u5217\uFF09\\n- \u6210\u54C1\u56FE\uFF1A\u65B0\u9C9C\u3001\u5065\u5EB7\u3001\u8868\u9762\u5E26\u7EC6\u5FAE\u6CB9\u5149\\n2. **\u5DE6\u7B2C\u4E8C\u680F\uFF08\u5FEB\u624B\u65E9\u9910\uFF09**\uFF1A\\n- \u83DC\u54C1\u6807\u9898\uFF1A\uFF08\u9700\u7F6E\u4E8E\u680F\u5185\u9876\u90E8\u5C45\u4E2D\uFF0C\u4E25\u683C\u6309\u4EA7\u54C1\u540D\u79F0\u751F\u6210\uFF09\\n- \u98DF\u6750\u5217\u8868\uFF1A\u6839\u636E\u98DF\u8C31\u4E25\u683C\u5199\u98DF\u6750\uFF08\u6BCF\u884C1\u79CD\u98DF\u6750\uFF0C\u524D\u7F6E\u25CF\u7B26\u53F7\uFF09\\n- \u6B65\u9AA4\u6587\u5B57\uFF1A\u6309\u98DF\u8C31\u7B80\u5355\u660E\u4E86\u5199\u51FA\u64CD\u4F5C\u6B65\u9AA4\uFF1B\u6BCF\u884C1\u4E2A\u6B65\u9AA4\uFF0C\u6309\u5E8F\u53F7\u6392\u5217\uFF09\\n- \u6210\u54C1\u56FE\uFF1A\u7ED9\u4EBA\u6709\u98DF\u6B32\u7B80\u5355\u597D\u5403\u6613\u5B66\\n3. **\u53F3\u7B2C\u4E09\u680F\uFF08\u5BB6\u5E38\u665A\u9910\uFF09**\uFF1A\\n- \u83DC\u54C1\u6807\u9898\uFF1A\uFF08\u9700\u7F6E\u4E8E\u680F\u5185\u9876\u90E8\u5C45\u4E2D\uFF0C\u4E25\u683C\u6309\u4EA7\u54C1\u540D\u79F0\u751F\u6210\uFF09\\n- \u98DF\u6750\u5217\u8868\uFF1A\u6309\u4EA7\u54C1\u540D\u79F0\u751F\u6210\u5BF9\u5E94\uFF08\u6BCF\u884C1\u79CD\u98DF\u6750\uFF0C\u524D\u7F6E\u25CF\u7B26\u53F7\uFF09\\n- \u6B65\u9AA4\u6587\u5B57\uFF1A\u6309\u4EA7\u54C1\u540D\u79F0\u751F\u6210\u5BF9\u5E94\uFF08\u6309\u5E8F\u53F7\u6392\u5217\uFF09\\n- \u6210\u54C1\u56FE\uFF1A\u83DC\u54C1\u76DB\u653E\u5728\u767D\u8272\u74F7\u76D8\u5185\uFF0C\u9EC4\u74DC\u5757\u7FE0\u7EFF\u5E26\u5149\u6CFD\u3001\u867E\u4EC1\u7C89\u767D\u9971\u6EE1\uFF0C\u8868\u9762\u5E26\u8F7B\u5FAE\u84B8\u6C7D\u8D28\u611F\uFF08\u6A21\u62DF\u521A\u51FA\u9505\u6548\u679C\uFF09\\n</\u5206\u680F\u7EC6\u8282>\\n\u4EE5\u4E0B\u662F\u6267\u884C\u89C4\u5219\uFF1A\\n<\u6267\u884C\u89C4\u5219>\\n- \u5FC5\u505A\uFF1A\u6BCF\u680F\u6A21\u5757\u987A\u5E8F\u4E25\u683C\u4E3A\u300C\u6807\u9898\u2192\u98DF\u6750\u2192\u6B65\u9AA4\u2192\u6210\u54C1\u56FE\u300D\uFF0C\u6210\u54C1\u56FE\u9700\u5360\u680F\u518560%\u9AD8\u5EA6\uFF0C\u6587\u5B57\u536040%\u9AD8\u5EA6\uFF1B\u6574\u4F53\u957F\u56FE\u6BD4\u4F8B\u4E3A3:2\uFF08\u5BBD\u5EA6\uFF1E\u9AD8\u5EA6\uFF09\uFF1B\u6807\u9898\u680F\u4E25\u683C\u6309\u5BF9\u5E94\u4EA7\u54C1\u540D\u79F0\u751F\u6210\uFF1B\u6392\u7248\u4E25\u683C\u6309\u5E03\u5C40\u8981\u6C42\u6267\u884C\\n- \u7981\u6B62\uFF1A\u4F7F\u7528\u6A21\u7CCA\u6EE4\u955C\u3001\u5938\u5F20\u9971\u548C\u5EA6\uFF0C\u7981\u6B62\u6587\u5B57\u91CD\u53E0\u6216\u906E\u6321\u98DF\u6750\u4E3B\u4F53\uFF0C\u7981\u6B62\u51FA\u73B0\u975E\u98DF\u8C31\u76F8\u5173\u5143\u7D20\uFF0C\u7981\u6B62\u51FA\u73B0\u8FDD\u7981\u8BCD\u548C\u82F1\u6587\u7EED\u5199\\n- \u4F18\u5148\u7EA7\uFF1A\u89C6\u89C9\u98DF\u6B32\u611F\u4F18\u5148\u4E8E\u6392\u7248\u5BC6\u5EA6\uFF0C\u82E5\u6587\u5B57\u8FC7\u591A\u53EF\u9002\u5F53\u7F29\u5C0F\u5B57\u53F7\uFF08\u4E0D\u4F4E\u4E8E10pt\uFF09\u4F46\u9700\u4FDD\u8BC1\u6E05\u6670\u53EF\u8BFB\uFF0C\u4E25\u683C\u6309\u7167\u6B63\u5E38\u6587\u7AE0\u6392\u7248\u903B\u8F91\\n</\u6267\u884C\u89C4\u5219>\\n\u8BF7\u57FA\u4E8E\u4E0A\u8FF0\u6240\u6709\u8981\u6C42\uFF0C\u751F\u6210\u9002\u914DAI\u4F5C\u56FE\u7684\u5C0F\u7EA2\u4E66\u98CE\u683C\u7F8E\u98DF\u957F\u56FE\u63D0\u793A\u8BCD\uFF0C\u8981\u6C42\u903B\u8F91\u6E05\u6670\u3001\u7EC6\u8282\u660E\u786E\u3001\u7B26\u5408AI\u4F5C\u56FE\u7684\u53C2\u6570\u5316\u8868\u8FBE\u4E60\u60EF\uFF0C\u8F93\u51FA\u5185\u5BB9\u9700\u5305\u542B\u6838\u5FC3\u8981\u6C42\u3001\u5206\u680F\u7EC6\u8282\u3001\u98CE\u683C\u5F3A\u5316\u3001\u6267\u884C\u89C4\u5219\u56DB\u4E2A\u90E8\u5206\u7684\u7ED3\u6784\u5316\u63CF\u8FF0\u3002","remark":"\u852C\u83DC\u8BE6\u60C5\u98753","owner":"lx1989","upvotes":3,"downvotes":0,"upvoteDifference":3,"updatedAt":"2026-04-13T20:38:51.753Z"}')}}]);